        if not match:
            raise ValueError(f"malformed item {item!r}")
        if match["star"]:
            start, end = low, high
        else:
            start = _value(match["start"], low, high, names)
            if match["end"] is not None:
                end = _value(match["end"], low, high, names)
                if start > end:
                    raise ValueError(f"backwards range {item!r}")
            elif match["step"] is not None:
                end = high
            else:
                end = start
        step = 1
        if match["step"] is not None:
            step = int(match["step"])
            if step == 0:
                raise ValueError(f"zero step in {item!r}")
        values.update(range(start, end + 1, step))
    return values


def _first_from(values: list[int], start: int) -> int | None:
    """The smallest of the sorted ``values`` that is at least ``start``."""
    for value in values:
        if value >= start:
            return value
    return None


def next_run(expression: str, after: datetime) -> datetime:
    """The first time after ``after`` that ``expression`` fires."""
    fields = expression.split()
    if len(fields) != 5:
        raise ValueError(f"expected 5 fields, got {len(fields)}")
    minutes, hours, days, months, weekdays = (
        _parse_field(text, *spec) for text, spec in zip(fields, _FIELDS)
    )
    minutes, hours = sorted(minutes), sorted(hours)
    weekdays = {weekday % 7 for weekday in weekdays}
    either = fields[2] != "*" and fields[4] != "*"

    def day_matches(day: date) -> bool:
        in_month = day.day in days
        # date.weekday() counts from Monday; cron counts from Sunday.
        in_week = (day.weekday() + 1) % 7 in weekdays
        return in_month or in_week if either else in_month and in_week

    start = after.replace(second=0, microsecond=0) + timedelta(minutes=1)
    try:
        limit = after.replace(year=after.year + 5)
    except ValueError:  # February 29th
        limit = after.replace(year=after.year + 5, day=28)

    day = start.date()
    while day <= limit.date():
        if day.month not in months:
            last = calendar.monthrange(day.year, day.month)[1]
            day += timedelta(days=last - day.day + 1)
            continue
        if day_matches(day):
            if day == start.date():
                hour = _first_from(hours, start.hour)
                minute = None
                if hour == start.hour:
                    minute = _first_from(minutes, start.minute)
                    if minute is None:
                        hour = _first_from(hours, start.hour + 1)
            else:
                hour = hours[0]
                minute = None
            if hour is not None:
                if minute is None:
                    minute = minutes[0]
                result = datetime.combine(day, time(hour, minute))
                if result > limit:
                    break
                return result
        day += timedelta(days=1)
    raise ValueError(f"{expression!r} does not fire within five years")
